import { BackgroundSyncPlugin } from 'workbox-background-sync';
import { clientsClaim } from 'workbox-core';
import { ExpirationPlugin } from 'workbox-expiration';
import { cleanupOutdatedCaches, matchPrecache, precacheAndRoute } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { CacheFirst, NetworkOnly, StaleWhileRevalidate } from 'workbox-strategies';

self.skipWaiting();
clientsClaim();
cleanupOutdatedCaches();

// Precache all assets generated by the build process
precacheAndRoute(self.__WB_MANIFEST);

// Background Sync for Firebase Functions (Drafts, Submissions)
const bgSyncPlugin = new BackgroundSyncPlugin('game-sync-queue', {
  maxRetentionTime: 24 * 60, // Retry for up to 24 hours
  onSync: async ({ queue }) => {
    // Notify clients that sync started
    const clients = await self.clients.matchAll();
    for (const client of clients) {
      client.postMessage({ type: 'SYNC_STARTED' });
    }

    try {
      await queue.replayRequests();
      // Notify clients that sync completed
      for (const client of clients) {
        client.postMessage({ type: 'SYNC_COMPLETED' });
      }
    } catch (error) {
      console.error('Background sync failed:', error);
    }
  },
});

registerRoute(
  ({ url }) => url.origin.includes('cloudfunctions.net'),
  new NetworkOnly({
    plugins: [bgSyncPlugin],
  }),
  'POST',
);

// Cache Google Fonts
registerRoute(
  ({ url }) => url.hostname === 'fonts.googleapis.com' || url.hostname === 'fonts.gstatic.com',
  new StaleWhileRevalidate({
    cacheName: 'google-fonts',
  }),
);

// Cache images
registerRoute(
  ({ request }) => request.destination === 'image',
  new CacheFirst({
    cacheName: 'images',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 60,
        maxAgeSeconds: 30 * 24 * 60 * 60, // 30 Days
      }),
    ],
  }),
);

// Network-first navigation handler for SPA routes, with precached CSR shell fallback when offline.
// Exclude .well-known, robots.txt, and sitemap.xml to let the server handle them.
registerRoute(
  ({ request, url }) =>
    request.mode === 'navigate' &&
    !url.pathname.startsWith('/.well-known/') &&
    url.pathname !== '/robots.txt' &&
    url.pathname !== '/sitemap.xml',
  async ({ request }) => {
    try {
      const networkResponse = await fetch(request, { cache: 'no-store' });
      if (networkResponse?.ok) {
        return networkResponse;
      }
    } catch {
      // Offline fallback below
    }
    return (
      (await matchPrecache('/index.csr.html')) ||
      (await matchPrecache('/index.html')) ||
      (await caches.match('/index.csr.html', { ignoreSearch: true })) ||
      (await caches.match('/index.html', { ignoreSearch: true })) ||
      fetch('/index.csr.html', { cache: 'no-store' })
    );
  },
);

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});
